const d=window.DOSSIER,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.hash.slice(1));let question=Math.min(2,Math.max(0,Number(params.get('q'))||0)),joined=params.get('join')==='1';
function save(){history.replaceState(null,'','#'+new URLSearchParams({q:question,object:$('#object').value,join:joined?'1':'0'}))}
function sources(ids){return '<div class="sources">'+ids.map(id=>{const s=d.sources.find(s=>s.id===id);return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗<span class="art-note"> (new tab)</span></a>`:''}).join('')+'</div>'}
$('#questions').insertAdjacentHTML('beforeend',d.campaign.questions.map((q,i)=>`<button data-q="${i}" aria-pressed="false">${esc(q.label)}</button>`).join(''));
const descriptions=[['A named representation of the assault.','Siege works and a destruction context.','An account of the wider campaign in Judah.','A narrative places the Assyrian king at Lachish.'],['The image associates Lachish with the campaign.','Layers give a relative sequence, not a calendar date.','The campaign supplies a historical anchor.','A named campaign can be compared with the deposits.'],['This image depicts Lachish, not Jerusalem.','These remains belong to a different city.','Confinement is claimed; capture is not.','The narrative explains survival as divine deliverance.']];
function renderQuestion(){const q=d.campaign.questions[question];document.querySelectorAll('[data-q]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.q)===question));q.cells.forEach((c,i)=>{$('#cell-'+i).innerHTML=`<strong class="cell-title">${esc(c)}</strong><p class="cell-description">${descriptions[question][i]}</p>`+sources(d.campaign.sources[i].sources)+(i===3?'<a href="http://127.0.0.1:8931/read/kjv/2KI/18?hl=13-17">Read 2 Kings 18–19 in context →</a>':'')});$('#finding').textContent=q.finding;$('#caution').textContent=q.caution}
document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{question=Number(b.dataset.q);renderQuestion();save()});
$('#record').innerHTML=d.campaign.sources.map((s,i)=>`<option value="${i}">${esc(s.label)}</option>`).join('');function record(){const s=d.campaign.sources[$('#record').value];$('#record-copy').innerHTML=`<h3>${esc(s.place)} / ${esc(s.voice)}</h3><p>${esc(s.observation)}</p><p>${esc(s.limit)}</p>${sources(s.sources)}`};$('#record').onchange=record;
function toggleRecord(open){$('#source-detail').hidden=!open;$('#inspect').setAttribute('aria-expanded',open);$('#inspect').textContent=open?'Close record ×':'Inspect a record ↓';if(!open){$('#inspect').focus({preventScroll:true});const r=$('#inspect').getBoundingClientRect();if(r.top<70||r.bottom>innerHeight)$('#inspect').scrollIntoView({block:'center',behavior:'auto'})}}
$('#inspect').onclick=()=>toggleRecord($('#source-detail').hidden);$('#close-record').onclick=()=>toggleRecord(false);
$('#dating').innerHTML=d.campaign.datingHistory.map(s=>`<li><span class="eyebrow">${esc(s.date)}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${sources(s.sources)}</li>`).join('');
$('#object').innerHTML=d.objects.map(o=>`<option value="${o.id}">${esc(o.name)} · ${esc(o.short)}</option>`).join('');$('#object').value=d.objects.some(o=>o.id===params.get('object'))?params.get('object'):'merneptah';
function object(){const o=d.objects.find(o=>o.id===$('#object').value),r=d.closeReadings[o.id];$('#object-copy').innerHTML=`<p class="eyebrow">${esc(o.place)} / ${esc(o.date)}</p><h3>${esc(o.question)}</h3><div class="object-pair"><div><h3>${esc(o.name)}</h3><p>${esc(o.summary)}</p><p class="art-note">${esc(o.form)} · ${esc(o.language)}</p><p>${esc(o.timeRelation)}</p>${sources(o.establishes.sources)}</div><div><span class="eyebrow">Biblical connection / editorial summary</span><h3><a href="http://127.0.0.1:8931${esc(o.passage.href)}">${esc(o.passage.label)} →</a></h3><p>${esc(o.passage.text)}</p><p>${esc(o.passage.relationship)}</p></div></div><div class="claim-lanes">${['establishes','suggests','unresolved'].map(k=>`<div><h4>${k[0].toUpperCase()+k.slice(1)}</h4><div><p>${esc(o[k].text)}</p>${sources(o[k].sources)}</div></div>`).join('')}</div><details><summary>Inspect the wording & details ↓</summary><p class="eyebrow">${esc(r.locator)} / ${esc(r.kind)}</p><h3>${esc(r.extract)}</h3>${sources([r.source])}${r.details.map(x=>`<h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>${sources(x.sources)}`).join('')}</details><details><summary>Findspot, dating & custody ↓</summary><dl>${Object.entries(o.record).filter(([k])=>k!=='sources').map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${sources(o.record.sources)}</details>`;}
$('#object').onchange=()=>{object();save()};function join(){const t=d.readingDisputes.telDan;$('#join').textContent=joined?'Proposed narrative connection':'Arrangement under examination';$('#join').classList.toggle('linked',joined);$('#join-switch').setAttribute('aria-pressed',joined);$('#join-switch').textContent=joined?'Separate the evidence again':'Show the traditional narrative link';$('#join-copy').textContent=(joined?t.traditional:t.challenge)+' '+t.stable;$('#join-sources').innerHTML=sources(t.sources)}$('#join-switch').onclick=()=>{joined=!joined;join();save()};renderQuestion();record();object();join();
